namespace Toolkit\DocGen\Render\Signature;

use function hash;
use function implode;
use function serialize;
use function strtolower;

use Toolkit\DocGen\Analysis\Model\ClassLikeDoc;
use Toolkit\DocGen\Analysis\Model\FunctionDoc;
